DO $patch$ DECLARE n text; d text; BEGIN FOR n IN SELECT unnest(ARRAY['treasure_v6_action','treasure_v5_action']) LOOP SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=n; d:=replace(d,'PERFORM public.energy_overflow_internal(u,greatest(0,e+10-100));',$new$s:=s||jsonb_build_object('overflowReceipt',public.energy_overflow_internal(u,greatest(0,e+10-100)));$new$); d:=replace(d,$old$'energy',e)$old$,$new$'energy',e,'overflowPoints',coalesce((s->>'overflowReceipt')::int,0))$new$); d:=replace(d,$old$ELSIF p_action='dig' THEN$old$,$new$ELSIF p_action='dig' THEN s:=s||'{"overflowReceipt":0}'::jsonb;$new$); EXECUTE d; END LOOP; END $patch$;